/*
 * A042616  Numerators of continued fraction convergents to sqrt(837).
 * https://oeis.org/A042616
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = Numerator of the n‑th convergent of √837 Recurrence: p_-2
 *            = 0, p_-1 = 1; p_n = a_n * p_{n-1} + p_{n-2}; The
 *            continued‑fraction coefficients a_n for √837 are generated by
 *            the standard quadratic‑irrational algorithm
 * Range:     u8 n <= 1, u16 n <= 5, u32 n <= 11, u64 n <= 25, u128 n <= 51,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static seq_t *cache      = NULL;   /* cache of computed numerators */
static size_t cache_cap  = 0;      /* allocated capacity of cache */
static idx_t  last_idx   = (idx_t)-1;   /* last index that has been computed */

/* state needed to generate the next coefficient a_{i+1} */
static seq_t  prev1 = 0;           /* p_{i-1} for the next iteration */
static seq_t  prev2 = 0;           /* p_{i-2} for the next iteration */
static uint64_t next_m = 0;        /* m value that generates the next a */
static uint64_t next_d = 1;        /* d value that generates the next a */

static const uint64_t D  = 837;    /* the quadratic discriminant */
static const uint64_t A0 = 28;    /* ⌊√837⌋ */

/* make sure the cache can hold indices up to n */
static void ensure_cache(idx_t n)
{
    if (cache == NULL) {
        /* initialise the first element and state */
        cache_cap = 16;
        cache = (seq_t*)malloc(cache_cap * sizeof(seq_t));
        if (!cache) abort();
        cache[0] = (seq_t)A0;          /* a(0) = 28 */
        prev1 = cache[0];
        prev2 = (seq_t)1;              /* p_-1 = 1 */

        /* initialise m and d for generating a_1 */
        uint64_t m1 = (uint64_t)A0;            /* d0 * a0 - m0 = 1*28 - 0 */
        uint64_t d1 = D - m1 * m1;             /* (D - m1^2)/d0, with d0 = 1 */
        next_m = m1;
        next_d = d1;
        last_idx = 0;
        return;
    }

    if ((size_t)n >= cache_cap) {
        size_t new_cap = cache_cap;
        while ((size_t)n >= new_cap) new_cap <<= 1;
        seq_t *tmp = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) abort();
        cache = tmp;
        cache_cap = new_cap;
    }
}

/* Numerator of the n-th convergent of √837 */
seq_t a(idx_t n)
{
    ensure_cache(n);

    if (n <= last_idx) {
        return cache[n];
    }

    /* current recurrence state */
    seq_t p_prev   = prev1;
    seq_t p_prev2  = prev2;
    uint64_t m_cur = next_m;
    uint64_t d_cur = next_d;

    for (idx_t i = last_idx + 1; i <= n; ++i) {
        seq_t a_i = (seq_t)((A0 + m_cur) / d_cur);   /* coefficient a_i */
        seq_t p   = a_i * p_prev + p_prev2;          /* numerator p_i */
        cache[i]  = p;

        /* advance recurrence state */
        p_prev2 = p_prev;
        p_prev  = p;

        /* compute next m and d */
        uint64_t m_next = d_cur * (uint64_t)a_i - m_cur;
        uint64_t d_next = (D - m_next * m_next) / d_cur;
        m_cur = m_next;
        d_cur = d_next;
    }

    /* update global state after computation */
    prev1 = p_prev;
    prev2 = p_prev2;
    next_m = m_cur;
    next_d = d_cur;
    last_idx = n;

    return cache[n];
}
